# word-level replacements applied only to HTML text nodes (between > and <) that contain no f-string braces
gen = [(r"\bdose-response\b", "use–symptom relation"), (r"\bcluster dose\b", "cluster-level use"), (r"\bthe dose\b", "the level of use"), (r"\bdose\b", "exposure level"),
       (r"\bthe pilot's nulls\b", "the pilot's no-effect results"), (r"\bcountry-level nulls\b", "country-level no-effect results"), (r"\bis null\b", "shows no effect"), (r"\bare null\b", "show no effect"), (r"\bThe LTE null\b", "The absence of an LTE effect"), (r"\bthe null GSHS\b", "the no-effect GSHS"), (r"\ba precise-enough null\b", "a reasonably precise zero"), (r"\bnull\b", "no effect"),
       (r"\bco-moves\b", "moves together"), (r"\bco-move\b", "move together"), (r"\bco-movement\b", "shared movement"),
       (r"\bfirst stage\b", "first step"), (r"\bco-primary\b", "main"), (r"\bthe plan's Part 0\b", "the design"), (r"\bthe plan\b", "the study design"),
       (r"\bshould update a little toward\b", "should conclude, a little more than before,"), (r"\bshould update toward\b", "should conclude"),
       (r"\bT2 arm\b", "school-pressure part"), (r"\bU\.S\. arm\b", "U.S. part of the study"), (r"\bthe international arms\b", "the international evidence"), (r"\bthis arm\b", "this part"), (r"\bthe HBSC arms\b", "the HBSC evidence"), (r"\bstate-survey and HBSC arms\b", "state-survey and HBSC evidence"),
       (r"\bcross-sectional\b", "one-time"), (r"\bIVW\b", "weighted"), (r"\bcells\b", "observations"), (r"\bspecification\b", "model"), (r"\bpre-register\b", "register in advance"),
       (r"\bH1 sign pattern\b", "pattern the phone hypothesis predicts"), (r"\bgirl-dominated\b", "concentrated in girls"), (r"\bplacebo\b", "placebo comparison")]
def fix_text(m):
    txt = m.group(2)
    if "{" in txt or "}" in txt: return m.group(0)
    for pat, repl in gen: txt = re.sub(pat, repl, txt)
    return m.group(1) + txt + m.group(3)
s = re.sub(r"(>)([^<>]+)(<)", fix_text, s); t = re.sub(r"(>)([^<>]+)(<)", fix_text, t)
s = s.replace("placebo comparison comparison", "placebo comparison").replace("5–9-year-old placebo comparison", "5–9-year-olds (a placebo comparison, since they are not the exposed group)")
p.write_text(s); r.write_text(t); print("language pass applied")
